mapper.select:
SELECT COUNT(*)
  FROM TB_MEMBER_COUPON
 WHERE MEMBER_NO = #{memberNo}
   AND COUPON_ID = #{couponId}

SELECT MC.MEMBER_COUPON_ID, C.COUPON_ID, C.COUPON_NAME, C.COUPON_TYPE, C.DISCOUNT_VALUE, C.MAX_DISCOUNT_AMT, C.MIN_ORDER_AMT, TO_CHAR(NVL(C.BIZ_NO, C.BIZ_MEMBER_NO)) AS BIZ_NO FROM TB_MEMBER_COUPON MC JOIN TB_COUPON C ON C.COUPON_ID = MC.COUPON_ID WHERE MC.MEMBER_NO = #{memberNo} AND MC.STATUS_CD = 'UNUSED' AND C.USE_END_DATE >= TO_CHAR(SYSDATE, 'YYYYMMDD') AND NVL(C.BIZ_NO, C.BIZ_MEMBER_NO) IN
#{bizNo}
ORDER BY MC.MEMBER_COUPON_ID
